import{_ as e,o as t,c as r,a2 as n}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Special Attacks y acciones preparadas","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/combat/special-attacks.md","filePath":"es/guide/combat/special-attacks.md"}'),o={name:"es/guide/combat/special-attacks.md"};function d(s,a,i,c,l,p){return t(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="special-attacks-and-prepared-actions" tabindex="-1">Special Attacks y acciones preparadas <a class="header-anchor" href="#special-attacks-and-prepared-actions" aria-label="Enlace permanente a &quot;Special Attacks y acciones preparadas&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto para el marco · Experimental para el conjunto de cinco ranuras · No implementado.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Las Special Attacks son técnicas aprendidas que después se seleccionan para un conjunto preparado.</li><li>El conjunto Experimental tiene 5 ranuras; las básicas no usan ninguna e INT todavía no lo escala.</li><li>La ofensiva se encola en Legacy y se activa en Modern; la defensa es manual y depende de disponibilidad en ambos.</li></ul><p>Las Special Attacks son técnicas aprendidas, no recompensas automáticas por alcanzar un valor de habilidad. Prepará un conjunto pequeño y elegí la acción adecuada para cada oportunidad.</p><h2 id="at-a-glance" tabindex="-1">De un vistazo <a class="header-anchor" href="#at-a-glance" aria-label="Enlace permanente a &quot;De un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tema</th><th>Dirección de prueba</th></tr></thead><tbody><tr><td>Aprendizaje</td><td>Maestros, manuales, escuelas, exploración y desafíos</td></tr><tr><td>Conocimiento</td><td>Las técnicas aprendidas siguen conocidas</td></tr><tr><td>Conjunto preparado</td><td>5 ranuras de SA; las básicas no usan ninguna; sin escalado por INT todavía</td></tr><tr><td>Acciones ofensivas</td><td>Legacy encola; Modern activa</td></tr><tr><td>Defensa</td><td>Manual en ambos modos, solo cuando las fases de acción lo permitan</td></tr><tr><td>Familiarity</td><td>Learned → Practiced → Mastered mejora modestamente la ejecución</td></tr></tbody></table><h2 id="first-weapon-kits" tabindex="-1">Primeros conjuntos de armas <a class="header-anchor" href="#first-weapon-kits" aria-label="Enlace permanente a &quot;Primeros conjuntos de armas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Arma</th><th>Básica</th><th>Tres opciones aprendidas</th></tr></thead><tbody><tr><td>Longsword</td><td>Basic Slash</td><td>Thrust, Feint, Riposte</td></tr><tr><td>Spear</td><td>Basic Thrust</td><td>Lunge, Brace, Sweep</td></tr><tr><td>War Hammer</td><td>Basic Swing</td><td>Heavy Blow, Crushing Arc, Guard Break</td></tr></tbody></table><h2 id="trade-offs" tabindex="-1">Ventajas y costes <a class="header-anchor" href="#trade-offs" aria-label="Enlace permanente a &quot;Ventajas y costes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elección</th><th>Propósito</th><th>Riesgo</th></tr></thead><tbody><tr><td>Feint</td><td>Provocar una respuesta defensiva temprana</td><td>Cuesta stamina; no causa daño directo</td></tr><tr><td>Brace / Riposte</td><td>Responder a un ataque compatible</td><td>Momento incorrecto, flanqueo o incompatibilidad desperdician el compromiso</td></tr><tr><td>Guard Break</td><td>Debilitar una postura activa para este golpe</td><td>Sin rotura permanente de armadura ni aturdimiento genérico</td></tr><tr><td>Arc</td><td>Presionar hasta dos hostiles cercanos</td><td>Menor precisión y recuperación costosa</td></tr></tbody></table><h2 id="preparation" tabindex="-1">Preparación <a class="header-anchor" href="#preparation" aria-label="Enlace permanente a &quot;Preparación&quot;">​</a></h2><ul><li>Una técnica debe ser conocida, estar preparada y ser compatible con el arma.</li><li>Los cambios de prueba requieren no tener objetivo, acción ni cola, y 10 segundos sin realizar/recibir acciones hostiles.</li><li>Cambiar nunca cancela la recuperación. Los futuros efectos de INT siguen sin resolverse.</li></ul><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un Brace preparado puede responder a un Heavy Blow comprometido. Feint puede provocarlo sin llegar a ejecutar ese golpe.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/combat/numeric-prototype.html">Costes de acciones</a> · <a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a> · <a href="/Syrolands-Public/es/game-design/combat/actions.html">Diseño completo</a></p>',17)])])}const m=e(o,[["render",d]]);export{h as __pageData,m as default};
